#include <algorithm>
#include <iostream>
#include <vector>

long long hoursNeeded(const std::vector<int>& piles, int speed) {
    long long hours = 0;
    for (int pile : piles) {
        hours += (pile + speed - 1) / speed;
    }
    return hours;
}

int minEatingSpeed(const std::vector<int>& piles, int h) {
    int lo = 1;
    int hi = *std::max_element(piles.begin(), piles.end());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (hoursNeeded(piles, mid) <= h) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> piles(n);
    for (int i = 0; i < n; i++) {
        std::cin >> piles[i];
    }
    int h;
    std::cin >> h;
    std::cout << minEatingSpeed(piles, h) << "\n";
    return 0;
}

