package main

import "fmt"

func hoursNeeded(piles []int, speed int) int64 {
	var hours int64
	for _, pile := range piles {
		hours += int64((pile + speed - 1) / speed)
	}
	return hours
}

func minEatingSpeed(piles []int, h int) int {
	lo, hi := 1, 0
	for _, pile := range piles {
		if pile > hi {
			hi = pile
		}
	}
	for lo < hi {
		mid := lo + (hi-lo)/2
		if hoursNeeded(piles, mid) <= int64(h) {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	return lo
}

func main() {
	var n int
	fmt.Scan(&n)
	piles := make([]int, n)
	for i := range piles {
		fmt.Scan(&piles[i])
	}
	var h int
	fmt.Scan(&h)
	fmt.Println(minEatingSpeed(piles, h))
}

